diff --git a/src/acl.c b/src/acl.c
index 1111111..2222222 100644
--- a/src/acl.c
+++ b/src/acl.c
@@ -1000,6 +1000,10 @@ static void aclInitUser(aclUser *user) {
     user->channels = NULL;
     user->pubsub_channels = NULL;
     user->commands = NULL;
+    user->flags &= ~(ACL_FLAG_SANITIZE_PAYLOAD);
+    if (server.sanitize_dump_enabled == ACL_SANITIZE_DUMP_CLIENTS) {
+        user->flags |= ACL_FLAG_SANITIZE_PAYLOAD;
+    }
 }
